(3033621, 425931, 15711, '<td valign="top">Clever. Very graphic. One of the few well done shots of the challenge!</td>', 'Clever. Very graphic. One of the few well done shots of the challenge!', '2006-11-15 09:13:56.000000', NULL, 1),
(3033633, 425870, 26425, '<td valign="top">I like this a lot!  Great lighting! Great idea!</td>', 'I like this a lot!  Great lighting! Great idea!', '2006-11-15 09:20:47.000000', NULL, 1),
(3033738, 426440, 41675, '<td valign="top">Nice clean, crisp photo. I like the placement of the pear and the use of negative space.</td>', 'Nice clean, crisp photo. I like the placement of the pear and the use of negative space.', '2006-11-15 10:07:44.000000', NULL, 1),
(3033739, 427267, 64929, '<td valign="top">Great shot...but is it "Spots?"</td>', 'Great shot...but is it "Spots?"', '2006-11-15 10:08:58.000000', NULL, 1),
(3033742, 426952, 41675, '<td valign="top">Cool - it''s what I''d imagine a psychadelic 60''s trip would have been like.</td>', 'Cool - it''s what I''d imagine a psychadelic 60''s trip would have been like.', '2006-11-15 10:09:38.000000', NULL, 1),
(3033750, 425527, 41675, '<td valign="top">Aside from the glow in the eye - nice capture. I like the tonal values. For me, the overall darkness adds to the "kill" effect.</td>', 'Aside from the glow in the eye - nice capture. I like the tonal values. For me, the overall darkness adds to the "kill" effect.', '2006-11-15 10:10:52.000000', NULL, 1),
