(3033847, 426949, 68426, '<td valign="top">Very good tones and textures and nice dof. I like your composition as well.</td>', 'Very good tones and textures and nice dof. I like your composition as well.', '2006-11-15 10:34:22.000000', NULL, 1),
(3033857, 427444, 68426, '<td valign="top">I love the left side of this leaf and the blurred background but maybe there needs to be more ''oomph'' in the right side of the leaf as it occupies so much of the frame.  Nice colour contrast.</td>', 'I love the left side of this leaf and the blurred background but maybe there needs to be more ''oomph'' in the right side of the leaf as it occupies so much of the frame.  Nice colour contrast.', '2006-11-15 10:36:25.000000', NULL, 1),
(3033868, 427192, 68426, '<td valign="top">The idea/focus/exposure etc are very good.  I think that the composition would be better if it were either completely symmetrical or more assymetrical.</td>', 'The idea/focus/exposure etc are very good.  I think that the composition would be better if it were either completely symmetrical or more assymetrical.', '2006-11-15 10:38:21.000000', NULL, 1),
