INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3034215, 427476, 66353, '<td valign="top">Looks a bit oversharpened to me - but I like the pose...</td>', 'Looks a bit oversharpened to me - but I like the pose...', '2006-11-15 12:32:59.000000', NULL, 1),
(3034233, 425752, 68582, '<td valign="top">I love the idea that this photo reflects the age of this little one.  Kind of a "double entendre" both with the title and the image.  Nicely focused foreground on the main subject of the challenge and the blurred background image of the "secondary" subject.  Nicely done!  Thumbs up!</td>', 'I love the idea that this photo reflects the age of this little one.  Kind of a "double entendre" both with the title and the image.  Nicely focused foreground on the main subject of the challenge and the blurred background image of the "secondary" subject.  Nicely done!  Thumbs up!', '2006-11-15 12:37:18.000000', NULL, 1),
(3034238, 425500, 67258, '<td valign="top">The image is very small, which does make it hard to critique.  That said, it is very ''busy'' without any aparant areas of sharpness or focus.</td>', 'The image is very small, which does make it hard to critique.  That said, it is very ''busy'' without any aparant areas of sharpness or focus.', '2006-11-15 12:37:43.000000', NULL, 1),
