(3034983, 427500, 37252, '<td valign="top">Cute idea. The focus seems too soft though and the white balance a bit off.</td>', 'Cute idea. The focus seems too soft though and the white balance a bit off.', '2006-11-15 16:12:32.000000', NULL, 1),
(3034984, 427555, 23484, '<td valign="top">I like the way this one done in B&amp;W. Nice shallow DOF. 7</td>', 'I like the way this one done in B&W. Nice shallow DOF. 7', '2006-11-15 16:12:33.000000', NULL, 1),
(3034996, 427192, 37252, '<td valign="top">Nice colors and detail. You had me stumped as to what this object was at first. I had to read the title to tell. This would work really good in an abstract challenge as well. Bumping you up to 8</td>', 'Nice colors and detail. You had me stumped as to what this object was at first. I had to read the title to tell. This would work really good in an abstract challenge as well. Bumping you up to 8', '2006-11-15 16:14:38.000000', NULL, 1),
(3035004, 427577, 37252, '<td valign="top">very nice b/w study. The perspective and DOF are perfect. Lovely lighting 8</td>', 'very nice b/w study. The perspective and DOF are perfect. Lovely lighting 8', '2006-11-15 16:17:21.000000', NULL, 1),
(3035008, 426119, 37252, '<td valign="top">I''m not one for floral shots usually, but putting aside my own personal prefs - this is very nice. The colors are complimentary, the focus dead on, and the use of DOF perfect.</td>', 'I''m not one for floral shots usually, but putting aside my own personal prefs - this is very nice. The colors are complimentary, the focus dead on, and the use of DOF perfect.', '2006-11-15 16:18:34.000000', NULL, 1),
(3035013, 425818, 37252, '<td valign="top">wow - good shot of a sunspot. Would love to know what filters you used to keep the brightness from blinding you. Obviously you used a telescope to capture this - would like to know what date you shot this and if it''ll bring us some nice aurora.</td>', 'wow - good shot of a sunspot. Would love to know what filters you used to keep the brightness from blinding you. Obviously you used a telescope to capture this - would like to know what date you shot this and if it''ll bring us some nice aurora.', '2006-11-15 16:20:00.000000', NULL, 1),
(3035014, 425451, 37252, '<td valign="top">wonderful detail and focus</td>', 'wonderful detail and focus', '2006-11-15 16:20:16.000000', NULL, 1),
(3035245, 426965, 60698, '<td valign="top">Great idea. Maybe a bit more color saturation to bring out the pretty colors.</td>', 'Great idea. Maybe a bit more color saturation to bring out the pretty colors.', '2006-11-15 17:15:40.000000', NULL, 1),
(3035290, 427220, 10943, '<td valign="top">I will be surprised if this doesn''t place.  Nice job.</td>', 'I will be surprised if this doesn''t place.  Nice job.', '2006-11-15 17:37:27.000000', NULL, 1),
