(3035298, 426119, 10943, '<td valign="top">Nice colors, good focus.  Nice job.  7</td>', 'Nice colors, good focus.  Nice job.  7', '2006-11-15 17:40:04.000000', NULL, 1),
(3035356, 427584, 65234, '<td valign="top">OMG, how in the world did you get a cat to pose like that?!  I am so impressed!!  Wish this was an advanced editing challenge so you could fix the pupils but I think the pose is a riot :-)</td>', 'OMG, how in the world did you get a cat to pose like that?!  I am so impressed!!  Wish this was an advanced editing challenge so you could fix the pupils but I think the pose is a riot :-)', '2006-11-15 18:02:49.000000', NULL, 1),
(3035363, 427559, 65234, '<td valign="top">They look well-used ;-)  I kind of like the off-balance composition; makes it feel like the die on top is going to fall off any second.  A little soft but I think that works with the other signs of age on the dice.</td>', 'They look well-used ;-)  I kind of like the off-balance composition; makes it feel like the die on top is going to fall off any second.  A little soft but I think that works with the other signs of age on the dice.', '2006-11-15 18:05:37.000000', NULL, 1),
(3035373, 427461, 65234, '<td valign="top">Very funky-looking landscape.  Almost looks like some kind of skeletal monster head over on the left, and one in the center/bottom too, now that I look more closely.  Looks like it could be a really fun place to experiment with angles and crops.</td>', 'Very funky-looking landscape.  Almost looks like some kind of skeletal monster head over on the left, and one in the center/bottom too, now that I look more closely.  Looks like it could be a really fun place to experiment with angles and crops.', '2006-11-15 18:09:03.000000', NULL, 1),
(3035376, 425798, 65234, '<td valign="top">Very sweet.  Wish I could see more of the dog, and I hope Patches'' eyes weren''t injured in the process of making this picture ;-)</td>', 'Very sweet.  Wish I could see more of the dog, and I hope Patches'' eyes weren''t injured in the process of making this picture ;-)', '2006-11-15 18:10:04.000000', NULL, 1),
(3035381, 427211, 65234, '<td valign="top">Spots upon a spot!  Not sure if I like the reflection but the light is certainly good enough to get the detail of the orange''s spotty texture.</td>', 'Spots upon a spot!  Not sure if I like the reflection but the light is certainly good enough to get the detail of the orange''s spotty texture.', '2006-11-15 18:12:23.000000', NULL, 1),
(3035391, 427068, 65234, '<td valign="top">Flower-Power Ducky looks well-used.  Or well-loved.  I feel like I want more definition in the bubbles to bring out those spots more ... or maybe bigger bubbles.  Good concept, though.</td>', 'Flower-Power Ducky looks well-used.  Or well-loved.  I feel like I want more definition in the bubbles to bring out those spots more ... or maybe bigger bubbles.  Good concept, though.', '2006-11-15 18:15:41.000000', NULL, 1),
(3035393, 427383, 65234, '<td valign="top">Original idea, and it looks like you have a lot of travelling in your future ;-)  Lighting is a little harsh and uneven.</td>', 'Original idea, and it looks like you have a lot of travelling in your future ;-)  Lighting is a little harsh and uneven.', '2006-11-15 18:16:43.000000', NULL, 1),
(3035396, 426895, 65234, '<td valign="top">Now there''s a different take on leopard spots LOL!  A bit snapshotty but I like the originality of it.</td>', 'Now there''s a different take on leopard spots LOL!  A bit snapshotty but I like the originality of it.', '2006-11-15 18:18:12.000000', NULL, 1),
(3035402, 427321, 65234, '<td valign="top">Oooh, pretty spots!  A few distracting bits and the blue/purple light is very bright, but this doesn''t look like an easy capture, especially for a basic editing challenge.</td>', 'Oooh, pretty spots!  A few distracting bits and the blue/purple light is very bright, but this doesn''t look like an easy capture, especially for a basic editing challenge.', '2006-11-15 18:20:27.000000', NULL, 1),
