(3035417, 427538, 65234, '<td valign="top">Cute pose.  More striped than spotty from what I can see, and the lighting is a little harsh.</td>', 'Cute pose.  More striped than spotty from what I can see, and the lighting is a little harsh.', '2006-11-15 18:27:31.000000', NULL, 1),
(3035419, 427178, 65234, '<td valign="top">Jammed?  OK, you probably got a million comments on the title ;-)  Interesting abstract with a bit of motion to it.</td>', 'Jammed?  OK, you probably got a million comments on the title ;-)  Interesting abstract with a bit of motion to it.', '2006-11-15 18:28:29.000000', NULL, 1),
(3035421, 426964, 65234, '<td valign="top">Not sure I get the title, but then I haven''t quite figured out what I''m looking at, either ;-)  Rather interesting!</td>', 'Not sure I get the title, but then I haven''t quite figured out what I''m looking at, either ;-)  Rather interesting!', '2006-11-15 18:30:18.000000', NULL, 1),
