(3038013, 426747, 45790, '<td valign="top">Certainly the best of the leopard shots in this contest. Great composition and very sharp.</td>', 'Certainly the best of the leopard shots in this contest. Great composition and very sharp.', '2006-11-16 14:12:37.000000', NULL, 1),
(3038015, 427245, 40718, '<td valign="top">Cute.  I like the composition, perspective and PP.  I wonder if a polarizer might have reduced the glare on a few of the leaves. 7</td>', 'Cute.  I like the composition, perspective and PP.  I wonder if a polarizer might have reduced the glare on a few of the leaves. 7', '2006-11-16 14:12:49.000000', NULL, 1),
