(3062647, 427190, 9668, '<td valign="top">Was DQed due to use of perspective cropping. Otherwise legal. Bummer.</td>', 'Was DQed due to use of perspective cropping. Otherwise legal. Bummer.', '2006-11-26 06:16:44.000000', NULL, 0),
(3063676, 426747, 11854, '<td valign="top">WOW! This is excellent! This is the type of shot I aspire to get. I love taking shots of the animals. Trying to get through that glass is mighty annoying. LOL. At the Philly zoo, between the low light conditions and the dirty glass it is a lesson in frustration most times. I usually take about 400 shots when we go to the zoo. At most maybe 30 come out decent (not good, but decent). Out of those 30, I might get 3 or 4 that are good. The sharpness on this is amazing. The colors are phenomenal.</td>', 'WOW! This is excellent! This is the type of shot I aspire to get. I love taking shots of the animals. Trying to get through that glass is mighty annoying. LOL. At the Philly zoo, between the low light conditions and the dirty glass it is a lesson in frustration most times. I usually take about 400 shots when we go to the zoo. At most maybe 30 come out decent (not good, but decent). Out of those 30, I might get 3 or 4 that are good. The sharpness on this is amazing. The colors are phenomenal.', '2006-11-26 19:16:57.000000', NULL, 0),
(3063744, 426747, 51538, '<td valign="top">The oasis of the eyes in the arid landscape make this photo appeal to me.</td>', 'The oasis of the eyes in the arid landscape make this photo appeal to me.', '2006-11-26 19:52:01.000000', NULL, 0),
(3064176, 427563, 54540, '<td valign="top">Very good first entry!<br/> <br/>I like the tight crop, and especially the contrast of the color of the eyes to the rest of the face.  The hand over the mouth is a good touch as well as is the hair.  Good composition!<br/> <br/>My two cents, the strong lighting would be worth experimenting with.  Could acheive a more dramatic or emotional effect with different angles, multiple lights.<br/> <br/>Welcome to DPC!  Looking forward to more!</td>', 'Very good first entry! I like the tight crop, and especially the contrast of the color of the eyes to the rest of the face.  The hand over the mouth is a good touch as well as is the hair.  Good composition! My two cents, the strong lighting would be worth experimenting with.  Could acheive a more dramatic or emotional effect with different angles, multiple lights. Welcome to DPC!  Looking forward to more!', '2006-11-26 23:13:33.000000', NULL, 0),
(3064193, 427192, 66494, '<td valign="top">What a creative mind you have. Love it. And use of my favorite ... copper. Beautiful (and it''s just a drain), but beautiful nonetheless.</td>', 'What a creative mind you have. Love it. And use of my favorite ... copper. Beautiful (and it''s just a drain), but beautiful nonetheless.', '2006-11-26 23:24:57.000000', NULL, 0),
(3064460, 425931, 50935, '<td valign="top">Great job on this! Gorgeous legs too.</td>', 'Great job on this! Gorgeous legs too.', '2006-11-27 00:38:27.000000', NULL, 0),
