(3065721, 427478, 30982, '<td valign="top">First, congratulations on a new "#1" on your top row, and a great score and placing!!  But mostly, congratulations on such a beautiful image.  You handled the color in this superbly, and the composition is wonderful.  What gorgeous pieces those starfish are!  Really a perfect picture!  Adding to my favorites.</td>', 'First, congratulations on a new "#1" on your top row, and a great score and placing!!  But mostly, congratulations on such a beautiful image.  You handled the color in this superbly, and the composition is wonderful.  What gorgeous pieces those starfish are!  Really a perfect picture!  Adding to my favorites.', '2006-11-27 11:52:08.000000', NULL, 0),
(3065826, 426965, 66709, '<td valign="top">awesome shot,  If you starred at for along time it can get sharping.</td>', 'awesome shot,  If you starred at for along time it can get sharping.', '2006-11-27 12:40:05.000000', NULL, 0),
